HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1];REPO=ROOT.parents[1]
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def path(p):
 p=Path(p);return p if p.is_absolute()else (REPO/p if p.parts and p.parts[0]=='research' else ROOT/p)
def same(a,b):return((a==b)|(a.isna()&b.isna())).fillna(False)
def number(s):return pd.to_numeric(s,errors='coerce').replace([np.inf,-np.inf],np.nan)
def ids(value):
 if isinstance(value,str):value=json.loads(value)
 if value is None:return[]
