def inventory(seed_ids,focal_mass,mass_by_id):
 seeds=ids(seed_ids);v=pd.Series([mass_by_id.get(k,np.nan)for k in seeds],dtype=float);ok=v.notna()&np.isfinite(v)&v.gt(0);focal=bool(pd.notna(focal_mass)and np.isfinite(focal_mass)and focal_mass>0)
 valid=len(seeds)>0 and ok.all();return{'observed_provider_seed_count':len(seeds),'observed_provider_missing_or_nonpositive_mass_count':int((~ok).sum()),'observed_provider_inventory_complete':bool(valid and focal),'comparable_provider_count':int(v.ge(.5*focal_mass).sum())if valid and focal else np.nan,'observed_provider_mass_hhi':float(((v/v.sum())**2).sum())if valid else np.nan}
def population_flags(member,focal_id):
 """Whole source cohort includes focal; rural cohort excludes exactly that ID only."""
 q=member.copy();q['additive']=q._population_axis_row.eq(True).fillna(False);q['external']=q.id.ne(focal_id);q['rural_external']=q.additive&q.external&q.accepted_statistical_rural_role2021.eq(True).fillna(False);q['unknown_role_external']=q.additive&q.external&q.accepted_statistical_rural_role2021.isna();q['weight2010']=number(q.population_2010).where(number(q.population_2010).ge(0));return q

def weighted_context(member,feature,minimum_coverage=.8):
 """2010-resident weighted mean; zero weights observed, missing weights never zero."""
 z=member[member.rural_external];weights=number(z.weight2010);value=number(z[feature]);valid=weights.notna()&value.notna();total=weights.sum(min_count=1);den=weights.where(valid).sum(min_count=1);num=(weights*value).where(valid).sum(min_count=1);coverage=den/total if pd.notna(total)and total>0 else np.nan;complete=weights.notna().all()and not member.unknown_role_external.any();mean=num/den if complete and pd.notna(coverage)and coverage>=minimum_coverage and den>0 else np.nan
 return {'weighted_mean':float(mean)if pd.notna(mean)else np.nan,'population_coverage2010':float(coverage)if pd.notna(coverage)else np.nan,'known_population2010_denominator':float(total)if pd.notna(total)else np.nan,'observed_feature_population2010_numerator':float(den)if pd.notna(den)else np.nan,'rural_members':len(z),'known_weight_members':int(weights.notna().sum()),'feature_observed_members':int(value.notna().sum()),'all_rural_weights_known':bool(weights.notna().all()),'unknown_role_external_members':int(member.unknown_role_external.sum()),'affirmative_complete_role_and_weights':bool(complete)}
def population_summary(member,focal_id,quality):
 q=member;result={};focal=q[q.id.eq(focal_id)];result['focal_membership_count']=len(focal);result['exact_one_focal_exclusion_supported']=len(focal)==1;result['rural_unknown_role_external_n']=int(q.unknown_role_external.sum());result['rural_members_n']=int(q.rural_external.sum());result['additive_members_n']=int(q.additive.sum())
 for year in [2010,2021]:
  pc=f'population_{year}';qc=f'population_value_quality_{year}';p=number(q[pc]).where(number(q[pc]).ge(0));fp=number(focal[pc])if len(focal)else pd.Series(dtype=float);fok=len(focal)==1 and fp.notna().all()and fp.ge(0).all();result[f'analysis_focal_own_population_complete_{year}']=bool(fok)
  for scope,mask in [('system',q.additive),('rural_external',q.rural_external)]:
   v=p[mask];complete=v.notna().all()and(scope=='rural_external'or len(v)>0);total=v.sum(min_count=1)if len(v)else(0. if scope=='rural_external'else np.nan);roleok=not q.unknown_role_external.any()if scope=='rural_external'else True;result[f'{scope}_population_known_sum_{year}']=float(total)if pd.notna(total)else np.nan;result[f'{scope}_population_complete_{year}']=bool(complete and roleok);result[f'analysis_{scope}{year}_primary_source_only']=bool(len(v)>0 and complete and q.loc[mask,qc].isin(quality[f'primary_population_quality_{year}']).all());wl=quality.get('primary_supported_population_quality_2010',quality['primary_population_quality_2010'])if year==2010 else quality['primary_population_quality_2021'];result[f'analysis_{scope}{year}_primary_supported_only']=bool(len(v)>0 and complete and q.loc[mask,qc].isin(wl).all())
   if year==2010:
    sec=q.loc[mask,qc].eq(quality['secondary_population_quality_2010']);num=v.where(sec,0).sum(min_count=1);result[f'analysis_{scope}2010_secondary_share_of_known_population']=float(num/total)if pd.notna(total)and total>0 else np.nan
  metro=q.id.isin(['ctx:RU-FED-MOW','ctx:RU-FED-SPB']);result[f'unknown_metropolitan_member_count_{year}']=int((metro&p.isna()).sum());result[f'analysis_whole_population_complete_{year}']=bool(result[f'system_population_complete_{year}']and fok and result[f'unknown_metropolitan_member_count_{year}']==0)
 valid=result['exact_one_focal_exclusion_supported']and result['analysis_whole_population_complete_2010']and result['analysis_whole_population_complete_2021'];a=result['system_population_known_sum_2010'];b=result['system_population_known_sum_2021'];valid=valid and pd.notna(a)and a>0 and pd.notna(b)and b>=0;result['outcome_system_change_pct']=100*(b/a-1)if valid else np.nan;result['outcome_system_log_change_100']=100*np.log(b/a)if valid and b>0 else np.nan;a=result['rural_external_population_known_sum_2010'];b=result['rural_external_population_known_sum_2021'];ok=result['exact_one_focal_exclusion_supported']and result['rural_external_population_complete_2010']and result['rural_external_population_complete_2021']and pd.notna(a)and a>0 and pd.notna(b)and b>=0;result['outcome_rural_change_pct']=100*(b/a-1)if ok else np.nan
 return result

def aggregate_member_frame(member,units,quality,features,minimum=.8):
    """Vectorized equivalent of population_summary/weighted_context on each unit."""
    q=population_flags(member,member.focal_id)
    idx=pd.Index(units.unit_id,name='unit_id');out=pd.DataFrame(index=idx)
    def count(mask):return mask.groupby(q.unit_id).sum().reindex(idx,fill_value=0).astype('int64')
    def total(values,mask,min_count=0):return values.where(mask).groupby(q.unit_id).sum(min_count=min_count).reindex(idx)
    focal=q.id.eq(q.focal_id);out['focal_membership_count']=count(focal);out['exact_one_focal_exclusion_supported']=out.focal_membership_count.eq(1);out['rural_unknown_role_external_n']=count(q.unknown_role_external);out['rural_members_n']=count(q.rural_external);out['additive_members_n']=count(q.additive)
    for year in [2010,2021]:
        p=number(q[f'population_{year}']).where(number(q[f'population_{year}']).ge(0));qual=q[f'population_value_quality_{year}'];out[f'analysis_focal_own_population_complete_{year}']=count(focal&p.notna()).eq(1)&out.exact_one_focal_exclusion_supported
        for scope,mask in [('system',q.additive),('rural_external',q.rural_external)]:
            n=count(mask);known=count(mask&p.notna());summed=total(p,mask,min_count=1);summed=summed.where(n.gt(0),0.)if scope=='rural_external'else summed;out[f'{scope}_population_known_sum_{year}']=summed;out[f'{scope}_source_members_n']=n;out[f'{scope}_known_population_members_n_{year}']=known;complete=known.eq(n)&(n.gt(0)if scope=='system'else True)
            if scope=='rural_external':complete&=out.rural_unknown_role_external_n.eq(0)
            out[f'{scope}_population_complete_{year}']=complete;pure=count(mask&p.notna()&qual.isin(quality[f'primary_population_quality_{year}'])).eq(n)&n.gt(0);support=quality.get('primary_supported_population_quality_2010',quality['primary_population_quality_2010'])if year==2010 else quality['primary_population_quality_2021'];out[f'analysis_{scope}{year}_primary_source_only']=pure;out[f'analysis_{scope}{year}_primary_supported_only']=count(mask&p.notna()&qual.isin(support)).eq(n)&n.gt(0)
            if year==2010:
                secondary=qual.eq(quality['secondary_population_quality_2010']);out[f'analysis_{scope}2010_secondary_share_of_known_population']=total(p,mask&secondary).fillna(0)/summed.where(summed.gt(0));out[f'analysis_{scope}2010_secondary_source_rows']=count(mask&secondary)
        out[f'unknown_metropolitan_member_count_{year}']=count(q.id.isin(['ctx:RU-FED-MOW','ctx:RU-FED-SPB'])&p.isna());out[f'analysis_whole_population_complete_{year}']=out[f'system_population_complete_{year}']&out[f'analysis_focal_own_population_complete_{year}']&out[f'unknown_metropolitan_member_count_{year}'].eq(0)
    a=out.system_population_known_sum_2010;b=out.system_population_known_sum_2021;ratio=b/a.where(a.gt(0));ok=out.analysis_whole_population_complete_2010&out.analysis_whole_population_complete_2021&a.gt(0)&b.ge(0);out['outcome_system_change_pct']=(100*(ratio-1)).where(ok);out['outcome_system_log_change_100']=(100*np.log(ratio.where(ratio.gt(0)))).where(ok);a=out.rural_external_population_known_sum_2010;b=out.rural_external_population_known_sum_2021;ok=out.rural_external_population_complete_2010&out.rural_external_population_complete_2021&out.exact_one_focal_exclusion_supported&a.gt(0)&b.ge(0);out['outcome_rural_change_pct']=(100*(b/a.where(a.gt(0))-1)).where(ok)
    rural=q.rural_external;w=q.weight2010;totalw=total(w,rural,min_count=1);knownw=count(rural&w.notna());completew=knownw.eq(out.rural_members_n);roles=out.rural_unknown_role_external_n.eq(0);basegate=completew&roles&out.exact_one_focal_exclusion_supported
    for feature in features:
        v=number(q[feature]);valid=rural&w.notna()&v.notna();den=total(w,valid,min_count=1);num=total(w*v,valid,min_count=1);coverage=den/totalw.where(totalw.gt(0));out[feature]=(num/den.where(den.gt(0))).where(basegate&coverage.ge(minimum));out[feature+'_population_coverage2010']=coverage;out[feature+'_known_population2010_denominator']=totalw;out[feature+'_observed_feature_population2010_numerator']=den;out[feature+'_rural_members']=out.rural_members_n;out[feature+'_known_weight_members']=knownw;out[feature+'_feature_observed_members']=count(rural&v.notna());out[feature+'_all_rural_weights_known']=completew;out[feature+'_unknown_role_external_members']=out.rural_unknown_role_external_n;out[feature+'_affirmative_complete_role_and_weights']=basegate
    return out

